from __future__ import absolute_import
import importlib
from selenium.webdriver.common.by import By
from taf.selenium.gnb.oam.coam.classical.pages.panels.navigation import NavigationPanel
from taf.selenium.gnb.oam.coam.classical.pages.panels.view import ViewPanel
from taf.selenium.gnb.oam.coam.classical.pages.panels.details import DetailPanel
from taf.selenium.gnb.oam.coam.classical.pages.navigatable_page import NavigatablePage
from taf.selenium.gnb.oam.coam.classical.pages.modals import CommissioningWizardModal


class CommissioningWizardPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Configuration', 'Configuration Management', 'Commissioning Wizard']

    def __init__(self, driver):
        super(CommissioningWizardPage, self).__init__(driver)
        self._navigation_panel = CommissioningWizardPageNavigationPanel(driver)
        self._view_panel = CommissioningWizardPageViewPanel(driver)
        self._detail_panel = CommissioningWizardPageDetailPanel(driver)
        self.index_value = None

    def add_cell(self, add_cell_type, add_cell_waiting_timeout):
        """
        keyword for add cell

        :param add_cell_type: str, "LTE FDD" or "Standalone NB IoT FDD"
        :param add_cell_waiting_timeout: int, time to wait finish cell adding
        """
        self._view_panel.add_cell(add_cell_type, add_cell_waiting_timeout)

    def configure_general_bts_site_settings(self, bts_name, timezone, bts_Id, product_variant_planned, additional_info):
        """
        Keyword for configuring general bts site settings

        :param bts_name: str, bts name
        :param timezone: str, timezone to be set while configuring general bts/site settings
        :param bts_Id: str, bts Id
        :param product_variant_planned: str, product variant planned
        :param additional_info: dict, dict of params with key value supported params are as follows
                                {'bts_description': 'value', 'configuration_type': 'value', 'region': 'value',
                                 'subregion':'value', 'group_name':'value', 'assignee':'value',
                                 'integration_info':'value', 'target_parameters_info':'value',
                                 'radio_topology_info':'value'}
        """
        self._view_panel.configure_general_bts_site_settings(bts_name, timezone,
                                                             bts_Id, product_variant_planned, additional_info)

    def configure_system_module_configuration(self, product_code, add_external_transport_unit,
                                              cabinet_position, module_location, climate_control_profile,
                                              radio_protocol_search_order):
        """
        Keyword for configuring system module configuration settings

        :param product_code: str, product code
        :param add_external_transport_unit: str, add external transport unit
        :param cabinet_position: str, cabinet position
        :param module_location: str, module_location
        :param climate_control_profile: str, climate control profile
        :param radio_protocol_search_order: str, radio protocol search order
        """
        self._view_panel.configure_system_module_configuration(product_code, add_external_transport_unit,
                                                               cabinet_position, module_location,
                                                               climate_control_profile,
                                                               radio_protocol_search_order)

    def configure_base_band_module_settings(self, product_code, bb_pools_used_per_bb_card,
                                            radio_protocol_search_order,
                                            baseband_pool_size_lte, position, bbmod_type):
        """
        Keyword for configuring base band module configuration settings

        :param product_code: str, product code
        :param bb_pools_used_per_bb_card: int, bb pools used per bb card
        :param radio_protocol_search_order: str, radio protocol search order
        :param baseband_pool_size_lte: str, baseband pool size lte
        :param position: str, position
        :param bbmod_type: str, by default bbmod type is 'BBMOD-1'. supported bbmod type are 'ABIL 474020A'
                           and 'ABIL 474020B'
        """
        self._view_panel.configure_base_band_module_settings(product_code, bb_pools_used_per_bb_card,
                                                             radio_protocol_search_order,
                                                             baseband_pool_size_lte, position, bbmod_type)

    def configure_radio_module_settings(self, product_code, module_location, abnormal_memory_threshold,
                                        link_speed, rmod_type):
        """
        Keyword for configuring radio module configuration settings

        :param product_code: str, product code
        :param module_location: str, module location
        :param abnormal_memory_threshold: int, abnormal memory threshold
        :param link_speed: str, link speed
        :param rmod_type: str, by default bbmod type is 'RMOD-1'
        """
        self._view_panel.configure_radio_module_settings(product_code, module_location,
                                                         abnormal_memory_threshold,
                                                         link_speed, rmod_type)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def navigate_to(self):
        """
        Check if commissioning wizard modal appear before call parent class navigate_to method
        """
        if not self._navigation_panel.is_modal_appear():
            super(CommissioningWizardPage, self).navigate_to()

    def go_to_target_path_under_commissioning_tab(self, target_tab_path, timeout):
        self.navigate_to()
        self._navigation_panel.go_to_commissioning_tab(target_tab_path, timeout)

    def submit(self):
        self._navigation_panel.submit()

    def configure_radio_module_link_configuration(self, start_point, available_rmod_modules, end_point,
                                                  radio_protocol_type, remove_cablink):
        """
        Keyword for configuring radio module link configuration settings

        :param start_point: str, start point required
        :param available_rmod_modules: str, available rmod modules
        :param end_point: str, end point
        :param radio_protocol_type: str, radio protocol type
        :param remove_cablink: In order to remove cablink, start_point name has to be provided by the user
                                e.g. "Q-RF1"
        """
        self._view_panel.configure_radio_module_link_configuration(start_point, available_rmod_modules, end_point,
                                                                   radio_protocol_type, remove_cablink)

    def configure_nr_tdd_basic_cell_settings(self, downlink_mimo_mode, uplink_mimo_mode,
                                             massive_mimo_antenna_array_mode, nr_cell_type,
                                             lte_nr_dynamic_spectrum_sharing, antenna, **kwargs):
        """
        Keyword for configuring nr tdd basic cell configuration settings

        :param cell_id: int cell id
        :param local_cell_resource_id: int, local cell resource id
        :param cell_name: str, cell name
        :param downlink_mimo_mode: str, downlink mimo mode
        :param uplink_mimo_mode: str, uplink mimo mode
        :param massive_mimo_antenna_array_mode: str, massive mimo antenna array mode
        :param nr_cell_type: str, nr cell type
        :param physical_layer_cell_id: int, physical layer cell id
        :param lte_nr_dynamic_spectrum_sharing: str, lte nr dynamic spectrum sharing
        :param antenna: str, antenna
        :param amount_of_tx_channels: int, amount of tx channels
        :param amount_of_rx_channels: int, amount of rx channels
        """
        self._view_panel.configure_nr_tdd_basic_cell_settings(downlink_mimo_mode, uplink_mimo_mode,
                                                              massive_mimo_antenna_array_mode, nr_cell_type,
                                                              lte_nr_dynamic_spectrum_sharing, antenna, **kwargs)

    def configure_nr_tdd_cell_carriers_settings(self, frequency_band_indicator_nr, bandwidth, nrarfcn, cell_power):
        """
        Keyword for configuring nr tdd cell carriers configuration settings

        :param frequency_band_indicator_nr: int, frequency band indicator nr required
        :param bandwidth: str, bandwidth
        :param nrarfcn: int, nrarfcn
        :param cell_power: str, cell power
        """
        self._view_panel.configure_nr_tdd_cell_carriers_settings(frequency_band_indicator_nr, bandwidth, nrarfcn,
                                                                 cell_power)

    def configure_nr_cell_group_basic_cell_settings(self, nr_cell_group_type, add_nr_cell_group,
                                                    sp_cell_change_enabled, beamforming_grip_sel,
                                                    number_of_transmitted_ss_blocks,
                                                    pucch_f2_max_code_rate,
                                                    scs, **kwargs):
        """
        Keyword for configuring nr cell group basic cell settings

        :param add_num_of_ho_users: int, additional number of user capacity for handovers
        :param add_num_of_nongbr_bearers_ho: int, additional number of non-GBR capacity for handovers
        :param add_num_of_rrccgrp_saho: int, additional number of RRC connected users in a new radio cell for
                                        SA handover
        :param beamforming_grip_sel: str, beamforming grid selection
        :param max_dl_harq_tx: int, maximum number of DL HARQ transmissions
        :param max_harq_msg3_tx: int, maximum number of Msg3 transmissions
        :param max_num_of_nongbr_bearers: int, maximum number of non-GBR data radio bearers
        :param max_num_of_nongbr_bearers_cgrp_sa: int, maximum number of non-GBR data radio bearers in new radio cell
                                                  group for SA
        :param max_num_of_rrc_cgrp_sa: int, maximum number of RRC connected users in a new radio cell group for SA
        :param max_num_of_users: int, maximum number of users in a NR cell group for NSA operation
        :param max_ul_harq_tx: int, maximum number of UL HARQ transmissions
        :param number_of_transmitted_ss_blocks: str, maximum number of UL HARQ transmissions
        :param pucch_f2_max_code_rate: str, pucch f2 max code rate
        :param scs: str, scs
        :param sp_cell_change_enabled: str, if SP-Cell change needs to enabled then giveit has,
                                       sp_cell_change_enabled='yes'
        :param ss_burst_set_period: int, SS burst set period
        :param ul_sched_time_interval: int, UL scheduling time interval
        :param add_nr_cell_group: str, if you wish to add nr cell group then give it has, add_nr_cell_group='yes'
        :param nr_cell_group_type: str, by default nr_cell_group_type='NRCELLGRP-0'
        """
        self._view_panel.configure_nr_cell_group_basic_cell_settings(nr_cell_group_type, add_nr_cell_group,
                                                                     sp_cell_change_enabled, beamforming_grip_sel,
                                                                     number_of_transmitted_ss_blocks,
                                                                     pucch_f2_max_code_rate,
                                                                     scs, **kwargs)

    def configure_nr_cell_assignment_to_group(self, nr_cell_group_id=None):
        """
        Keyword for configuring nr cell assignment to group

        :param nr_cell_group_id: str, nr cell group id
        """
        self._view_panel.configure_nr_cell_assignment_to_group(nr_cell_group_id=nr_cell_group_id)

    def configure_basic_nr_rat_configuration(self, gnb_cu_type, restore_gnb_id, **kwargs):
        """
        Keyword for basic nr rat configuration

        :param gnb_id: int, gnb id
        :param mobile_country_code: int, mobile country code
        :param mobile_network_code: int, mobile network code
        :param mobile_network_code_length: int, mobile network code length
        :param gnb_cu_type: str, gnb cu type
        :param restore_gnb_id: str, if you wish to restore gnb id then give it has, restore_gnb_id='yes'
        """
        self._view_panel.configure_basic_nr_rat_configuration(gnb_cu_type, restore_gnb_id, **kwargs)


class CommissioningWizardPageNavigationPanel(NavigationPanel):
    _STEPS_TABLE_XPATH = '//*[text()="Navigation Panel"]/ancestor::wf-panel//*[text()="Steps"]'
    _GENERAL_BTS_SITE_SETTINGS_XPATH = '//div[@title="General BTS/Site Settings"]'
    _COMMISSION_WIZARD_MODAL_XPATH = '//div[@class="modal-content"][//*[contains(@title, "Commissioning Wizard")]]'
    _TAB_NAME_MAPPING_METHODS_TABLE = {}
    _TARGET_TAB_PATH = None

    def __init__(self, driver):
        super(CommissioningWizardPageNavigationPanel, self).__init__(driver)
        self._commissioning_wizard_modal = CommissioningWizardModal(driver)
        self._dynamic_add_methods(driver)

    def is_modal_appear(self):
        return self._commissioning_wizard_modal.is_modal_appear

    def _dynamic_add_methods(self, driver):
        module = importlib.import_module(
            'taf.selenium.gnb.oam.coam.classical.pages.configuration.configuration_management.'
            'commissioning_wizard.commissioning_wizard_settings'
        )
        for item in dir(module):
            if not item[0].isupper():
                continue
            cls = getattr(module, item)
            cls_obj = cls(driver)
            for method_name in cls_obj.get_method_list():
                self._TAB_NAME_MAPPING_METHODS_TABLE.update(
                    {cls_obj._tab_name: {method_name: getattr(cls_obj, method_name)}}
                )

    def _open_modal(self, timeout=60):
        if not self._commissioning_wizard_modal.is_modal_appear:
            self.click_enabled_element((By.XPATH, self._STEPS_TABLE_XPATH))
            self.click_enabled_element((By.XPATH, self._GENERAL_BTS_SITE_SETTINGS_XPATH))
            self._commissioning_wizard_modal.wait_for_commissioning_wizard_modal_appear(timeout)

    def __getattribute__(self, value):
        if value == "_TAB_NAME_MAPPING_METHODS_TABLE" or value == '_TARGET_TAB_PATH':
            return super(CommissioningWizardPageNavigationPanel, self).__getattribute__(value)
        methods_dict = self._TAB_NAME_MAPPING_METHODS_TABLE.get(self._TARGET_TAB_PATH, None)
        if methods_dict and value in methods_dict:
            return methods_dict[value]
        else:
            return super(CommissioningWizardPageNavigationPanel, self).__getattribute__(value)

    def go_to_commissioning_tab(self, target_tab_path, timeout):
        self._open_modal(timeout)

        self._TARGET_TAB_PATH = target_tab_path
        commissioning_wizard_modal_xpath = ('//div[@class="modal-content"]'
                                            '[//*[contains(@title, "Commissioning Wizard")]]')
        input_xpath = commissioning_wizard_modal_xpath + '//*[@*="Step name"]//input'

        target_tab_path = target_tab_path.split('/')[::-1]
        target_tab = target_tab_path[0]
        target_tab_xpath = '//wizard-steps-modal-body//span[contains(text(), "{}")]'.format(target_tab)

        self.insert_text_to_enable_element_and_enter((By.XPATH, input_xpath), target_tab)
        self.wait_for_visibility_by_xpath(target_tab_xpath)
        if len(self.driver.find_elements_by_xpath(target_tab_xpath)) > 1:
            target_tab_xpath = (commissioning_wizard_modal_xpath
                                + '//wizard-steps-modal-body//span[contains(text(), "{}")]'
                                  '/ancestor::li/following-sibling::li[1]'.format(target_tab_path[1])
                                + '//span[contains(text(), "{}")]'.format(target_tab))
        self.click_enabled_element((By.XPATH, target_tab_xpath))


class CommissioningWizardPageViewPanel(ViewPanel):
    _ADD_CELL_BTN_XPATH = '//div[contains(@class,"CELL-column")]//div[@class="site-widget"]//button/i[@class="plus"]'
    _ADD_CELL_TYPE_XPATH = ('//div[contains(@class,"CELL-column")]//div[@class="site-widget"]'
                            '//div[@class="hw-element-select-wrapper"]//div[text()="{}"]')

    def __init__(self, driver):
        super(CommissioningWizardPageViewPanel, self).__init__(driver)
        self.index_value = None

    def add_cell(self, add_cell_type, add_cell_waiting_timeout):
        self.click_enabled_element_after_visible((By.XPATH, self._ADD_CELL_BTN_XPATH), add_cell_waiting_timeout)
        self.click_enabled_element_after_visible((By.XPATH, self._ADD_CELL_TYPE_XPATH.format(add_cell_type)))

    def _insert_text_to_enable_element(self, system_key, system_value):
        if system_value is not None:
            self.insert_text_to_enable_element(system_key, system_value)

    def _click_enabled_element_on_system_module_config(self, system_key, system_value, module_config,
                                                       select_dropdown=None):
        if select_dropdown is not None:
            select_dropdown_item = select_dropdown
        else:
            select_dropdown_item = self._SELECT_DROPDOWN_ITEM
        if system_value is not None:
            self.click_enabled_element(module_config.format(system_key))
            self.click_enabled_element(
                module_config.format(system_key) + select_dropdown_item.format(system_value))

    def _click_on_pop_up(self, pop_up_path, timeout=10):
        if self.element_exists(pop_up_path, timeout=timeout):
            self.click_enabled_element(pop_up_path)

    def _general_bts_site_settings_additional_info(self, additional_info):
        if additional_info is not None:
            for key, value in additional_info.items():
                if key == 'radio_topology_info':
                    self._insert_text_to_enable_element(system_key=self._RADIO_TOPOLOGY_INFO, system_value=value)
                else:
                    self._insert_text_to_enable_element(
                        system_key=self._TARGET_INFO.format(self.general_bts_site_settings_dict[key]),
                        system_value=value)

    def configure_general_bts_site_settings(self, bts_name, timezone, bts_Id, product_variant_planned, additional_info):
        self._insert_text_to_enable_element(
            system_key=self._TARGET_INFO.format(self.general_bts_site_settings_dict['bts_name']),
            system_value=bts_name)
        self._click_enabled_element_on_system_module_config(system_key=self.general_bts_site_settings_dict['timezone'],
                                                            system_value=timezone,
                                                            module_config=self._TIMEZONE_BUTTON)
        self._insert_text_to_enable_element(
            system_key=self._TARGET_INFO.format(self.general_bts_site_settings_dict['bts_Id']),
            system_value=bts_Id)
        self.click_enabled_element(self._BTS_ID)
        self._click_on_pop_up(self._APPLY_BUTTON)
        self._click_enabled_element_on_system_module_config(
            system_key=self.general_bts_site_settings_dict['product_variant_planned'],
            system_value=product_variant_planned,
            module_config=self._TIMEZONE_BUTTON)
        self._click_on_pop_up(self._PRODUCT_VARIANT_PLANNED_CONFIG)
        self._general_bts_site_settings_additional_info(additional_info=additional_info)
        self.click_enabled_element(self._DONE_BUTTON)

    def configure_system_module_configuration(self, product_code, add_external_transport_unit,
                                              cabinet_position, module_location, climate_control_profile,
                                              radio_protocol_search_order):
        self.click_enabled_element(self._SYSTEM_MODULE_LIST_BUTTON)
        self._click_enabled_element_on_system_module_config(
            system_key=self.system_module_config_dict['product_code'], system_value=product_code,
            module_config=self._SYSTEM_MODULE_DROPDOWN)
        self._click_enabled_element_on_system_module_config(
            system_key=self.system_module_config_dict['add_external_transport_unit'],
            system_value=add_external_transport_unit, module_config=self._SYSTEM_MODULE_DROPDOWN)
        self._click_enabled_element_on_system_module_config(
            system_key=self.system_module_config_dict['cabinet_position'], system_value=cabinet_position,
            module_config=self._SYSTEM_MODULE_DROPDOWN)
        self._insert_text_to_enable_element(system_key=self._MODULE_LOCATION, system_value=module_location)
        self._click_enabled_element_on_system_module_config(
            system_key=self.system_module_config_dict['climate_control_profile'],
            system_value=climate_control_profile, module_config=self._SYSTEM_MODULE_DROPDOWN)
        self._click_enabled_element_on_system_module_config(
            system_key=self.system_module_config_dict['radio_protocol_search_order'],
            system_value=radio_protocol_search_order, module_config=self._SYSTEM_MODULE_DROPDOWN)
        self.click_enabled_element(self._DONE_BUTTON)

    def _collapse_right_button(self):
        if self.element_exists(self._COLLAPSE_RIGHT_BUTTON, timeout=5):
            self.click_enabled_element(self._COLLAPSE_RIGHT_BUTTON)

    def _get_all_matching_elements_from_base_band_module(self, add_bbmod, bbmode_dropdown, bbmode_type, match_element):
        self.click_enabled_element(add_bbmod + bbmode_dropdown)
        self.click_enabled_element(add_bbmod + self._SELECT_DROPDOWN_ITEM.format(bbmode_type))
        self.get_all_matching_elements(self._BASE_BAND_MATCH_ELEMENT.format(match_element))[-1].click()

    def configure_base_band_module_settings(self, product_code, bb_pools_used_per_bb_card,
                                            radio_protocol_search_order, baseband_pool_size_lte, position,
                                            bbmod_type):
        self._collapse_right_button()
        if bbmod_type != 'BBMOD-1':
            self._get_all_matching_elements_from_base_band_module(add_bbmod=self._ADD_BBMOD,
                                                                  bbmode_dropdown=self._ADD_BBMOD_DROPDOWN,
                                                                  bbmode_type=bbmod_type,
                                                                  match_element=bbmod_type.split(' ')[0])
        else:
            self.click_enabled_element(self._SELECT_BBMOD.format('BBMOD-1'))
        if product_code:
            self.click_enabled_element(self._FIX_PRODUCT_CODE_MISMTACH)
        self._insert_text_to_enable_element(system_key=self._BB_CARD.format('BB pools used per BB card'),
                                            system_value=bb_pools_used_per_bb_card)
        self._click_enabled_element_on_system_module_config(
            system_key=self.baseband_module_config_dict['radio_protocol_search_order'],
            system_value=radio_protocol_search_order, module_config=self._BASEBAND_MODULE_DROPDOWN)
        self._click_enabled_element_on_system_module_config(
            system_key=self.baseband_module_config_dict['baseband_pool_size_lte'],
            system_value=baseband_pool_size_lte, module_config=self._BASEBAND_MODULE_DROPDOWN)
        self._click_enabled_element_on_system_module_config(
            system_key=self.baseband_module_config_dict['position'],
            system_value=position, module_config=self._BASEBAND_MODULE_DROPDOWN)
        self.click_enabled_element(self._DONE_BUTTON)

    def configure_radio_module_settings(self, product_code, module_location, abnormal_memory_threshold,
                                        link_speed, rmod_type):
        self._collapse_right_button()
        if rmod_type != 'RMOD-1':
            self._get_all_matching_elements_from_base_band_module(add_bbmod=self._ADD_RMOD,
                                                                  bbmode_dropdown=self._ADD_RMOD_DROPDOWN,
                                                                  bbmode_type=rmod_type,
                                                                  match_element=rmod_type.split(' ')[0])
        else:
            self.click_enabled_element(self._SELECT_BBMOD.format('RMOD-1'))
        if product_code:
            self.click_enabled_element(self._FIX_PRODUCT_CODE_MISMTACH)
        self._insert_text_to_enable_element(system_key=self._BB_CARD.format('Module location'),
                                            system_value=module_location)
        self._insert_text_to_enable_element(system_key=self._BB_CARD.format('Abnormal memory threshold'),
                                            system_value=abnormal_memory_threshold)
        self._click_enabled_element_on_system_module_config(system_key='Link speed',
                                                            system_value=link_speed,
                                                            module_config=self._BASEBAND_MODULE_DROPDOWN)
        self.click_enabled_element(self._DONE_BUTTON)

    def _click_radio_module_link_dropdown(self, start_point, radio_column, radio_link_type):
        if radio_link_type is not None:
            self.click_enabled_element(self._RADIO_MODULE_LINK_DROPDOWN.format(start_point, radio_column))
            self.click_enabled_element(self._RADIO_MODULE_LINK_DROPDOWN.format
                                       (start_point, radio_column) + self._RADIO_MODULE_LINK_INSERT.format
                                       (radio_link_type))

    def configure_radio_module_link_configuration(self, start_point, available_rmod_modules, end_point,
                                                  radio_protocol_type, remove_cablink):
        self.click_enabled_element(self._RADIO_MODULE_LINK)
        self._click_radio_module_link_dropdown(start_point=start_point, radio_column=2,
                                               radio_link_type=available_rmod_modules)
        self._click_radio_module_link_dropdown(start_point=start_point, radio_column=3,
                                               radio_link_type=end_point)
        self._click_radio_module_link_dropdown(start_point=start_point, radio_column=4,
                                               radio_link_type=radio_protocol_type)
        if remove_cablink:
            self.click_enabled_element(self._REMOVE_CABLINK.format(remove_cablink))
        self.click_enabled_element(self._DONE_BUTTON)

    def _click_enable_element_on_nr_tdd_basic_cell_settings(self, mode_type, mode_value, select_dropdown=None):
        self._click_enabled_element_on_system_module_config(system_key=mode_type,
                                                            system_value=mode_value,
                                                            module_config=self._BASEBAND_MODULE_DROPDOWN,
                                                            select_dropdown=select_dropdown)

    def _amount_of_tx_rx_channels(self, tx_rx_key, tx_rx_value, index_value=3):
        self._insert_text_to_enable_element(
            system_key=self._AMOUNT_OF_TX.format(
                self.configure_nr_tdd_basic_cell_settings_dict[tx_rx_key], index_value),
            system_value=tx_rx_value)

    def _nr_cell_dict(self, nr_dict='nr_cell_group'):
        if nr_dict == 'nr_cell_group':
            nr_dict = self.configure_nr_cell_group_basic_cell_settings_dict
        elif nr_dict == 'nr_rat_config':
            nr_dict = self.configure_basic_nr_rat_configuration_dict
        else:
            nr_dict = self.configure_nr_tdd_basic_cell_settings_dict
        return nr_dict

    def _insert_element_on_configure_nr_tdd_basic_cell_settings(self, nr_dict=None, **kwargs):
        nr_dict = self._nr_cell_dict(nr_dict=nr_dict)
        for key, value in kwargs.items():
            if value is not None:
                if key == 'amount_of_tx_channels':
                    self._amount_of_tx_rx_channels(key, value)
                elif key == 'amount_of_rx_channels':
                    self._amount_of_tx_rx_channels(key, value, 4)
                else:
                    self._insert_text_to_enable_element(
                        system_key=self._BB_CARD.format(nr_dict[key]),
                        system_value=value)
                    if key == 'gnb_id':
                        self.click_enabled_element(self._GNB_ID_XPATH)
                        self._click_on_pop_up(self._APPLY_BUTTON)

    def _click_element_on_configure_nr_cell_group_basic_cell_settings(self, group_dict, mode_type='nr_cell_group'):
        if mode_type != 'nr_cell_group':
            mode_type = self.configure_nr_tdd_basic_cell_settings_dict
        else:
            mode_type = self.configure_nr_cell_group_basic_cell_settings_dict
        for key, value in group_dict.items():
            self._click_enable_element_on_nr_tdd_basic_cell_settings(
                mode_type=mode_type[key],
                mode_value=value)

    def configure_nr_tdd_basic_cell_settings(self, downlink_mimo_mode, uplink_mimo_mode,
                                             massive_mimo_antenna_array_mode, nr_cell_type,
                                             lte_nr_dynamic_spectrum_sharing, antenna, **kwargs):
        self._collapse_right_button()
        self.get_all_matching_elements(self._NR_CELL_TYPE.format('NRCELL'))[-1].click()
        self._insert_element_on_configure_nr_tdd_basic_cell_settings(**kwargs)
        nr_tdd_basic_cell_dict = {'downlink_mimo_mode': downlink_mimo_mode,
                                  'uplink_mimo_mode': uplink_mimo_mode,
                                  'massive_mimo_antenna_array_mode': massive_mimo_antenna_array_mode,
                                  'nr_cell_type': nr_cell_type,
                                  'lte_nr_dynamic_spectrum_sharing': lte_nr_dynamic_spectrum_sharing}
        self._click_element_on_configure_nr_cell_group_basic_cell_settings(group_dict=nr_tdd_basic_cell_dict,
                                                                           mode_type='tdd_basic_cell')
        self._click_enabled_element_on_system_module_config(system_key='AEQV',
                                                            system_value=antenna,
                                                            module_config=self._NR_CHANNEL_DROPDOWN)
        self.click_enabled_element(self._DONE_BUTTON)

    def configure_nr_tdd_cell_carriers_settings(self, frequency_band_indicator_nr, bandwidth, nrarfcn, cell_power):
        self._collapse_right_button()
        self.get_all_matching_elements(self._NR_TDD_CELL_CARRIERS.format('NRCELL'))[-1].click()
        self._insert_text_to_enable_element(system_key=self._BB_CARD.format('Frequency band Indicator NR'),
                                            system_value=frequency_band_indicator_nr)
        self._click_enable_element_on_nr_tdd_basic_cell_settings(mode_type='Bandwidth', mode_value=bandwidth)
        self._insert_text_to_enable_element(system_key=self._BB_CARD.format('NRARFCN'), system_value=nrarfcn)
        self._click_enable_element_on_nr_tdd_basic_cell_settings(mode_type='Cell power', mode_value=cell_power)
        self.click_enabled_element(self._DONE_BUTTON)

    def configure_nr_cell_group_basic_cell_settings(self, nr_cell_group_type, add_nr_cell_group,
                                                    sp_cell_change_enabled, beamforming_grip_sel,
                                                    number_of_transmitted_ss_blocks,
                                                    pucch_f2_max_code_rate,
                                                    scs, **kwargs):
        self._collapse_right_button()
        if add_nr_cell_group:
            self.click_enabled_element(self._ADD_NR_CELL_GROUP)
        if nr_cell_group_type:
            self.click_enabled_element(self._NR_CELL_GROUP_TYPE.format(nr_cell_group_type))
        if sp_cell_change_enabled:
            self.click_enabled_element(self._NR_CELL_GRP_CHECKBOX)
        self._insert_element_on_configure_nr_tdd_basic_cell_settings(nr_dict='nr_cell_group', **kwargs)
        nr_cell_group_dict = {'beamforming_grip_sel': beamforming_grip_sel,
                              'number_of_transmitted_ss_blocks': number_of_transmitted_ss_blocks,
                              'pucch_f2_max_code_rate': pucch_f2_max_code_rate,
                              'scs': scs}
        self._click_element_on_configure_nr_cell_group_basic_cell_settings(group_dict=nr_cell_group_dict)
        self.click_enabled_element(self._DONE_BUTTON)

    def configure_nr_cell_assignment_to_group(self, nr_cell_group_id=None):
        if nr_cell_group_id is not None:
            self.click_enabled_element(self._NR_CELL_ASSIGNMENT_GROUP)
            self.click_enabled_element(
                self._NR_CELL_ASSIGNMENT_GROUP + self._NR_CELL_INSERT_VALUE.format(nr_cell_group_id))
        self.click_enabled_element(self._DONE_BUTTON)

    def configure_basic_nr_rat_configuration(self, gnb_cu_type, restore_gnb_id, **kwargs):
        self._insert_element_on_configure_nr_tdd_basic_cell_settings(nr_dict='nr_rat_config', **kwargs)
        self._click_enable_element_on_nr_tdd_basic_cell_settings(mode_type='gNB CU type', mode_value=gnb_cu_type,
                                                                 select_dropdown=self._RADIO_MODULE_LINK_INSERT)
        if restore_gnb_id:
            if self.element_exists(self._RESTORE_GNB_ID_BUTTON_DISABLED):
                raise RuntimeError("Failed to restore element due to button disabled")
            self.click_enabled_element(self._RESTORE_GNB_ID_BUTTON)
            self._click_on_pop_up(self._APPLY_BUTTON)
        self.click_enabled_element(self._DONE_BUTTON)


class CommissioningWizardPageDetailPanel(DetailPanel):
    def __init__(self, driver):
        super(CommissioningWizardPageDetailPanel, self).__init__(driver)
